// Data store — the ONLY place that knows where content lives.
// Screens never hard-code puzzle data; everything comes from data/
// (regenerated by tools/sync_from_game.py when the game changes).

const fetchJson = async (url) => {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Failed to load ${url} (${res.status})`);
  return res.json();
};

let manifestPromise = null;
let themePromise = null;
const packCache = new Map();

export const store = {
  getManifest() {
    manifestPromise ??= fetchJson('data/manifest.json');
    return manifestPromise;
  },

  getTheme() {
    themePromise ??= fetchJson('data/theme.json');
    return themePromise;
  },

  async getPack(packId) {
    if (packCache.has(packId)) return packCache.get(packId);
    const manifest = await this.getManifest();
    for (const track of manifest.tracks) {
      const pack = track.packs.find((p) => p.id === packId);
      if (pack) {
        const json = await fetchJson(`data/levels/${pack.file}`);
        packCache.set(packId, { pack, track, json });
        return packCache.get(packId);
      }
    }
    return null;
  },

  worldForTrack(theme, trackId) {
    const worldId = theme.trackWorld[trackId] || 'clearspace';
    return { id: worldId, ...theme.worlds[worldId] };
  },

  tracksWithPacks(manifest) {
    return manifest.tracks.filter((t) => t.packs.length > 0);
  },
};

// Find a level (puzzle) inside a pack by journey position.
export function findPuzzle(packJson, level, puzzle) {
  return packJson.levels.find(
    (l) => (l.journeyPosition?.level ?? 0) === level && (l.journeyPosition?.puzzle ?? 0) === puzzle,
  ) || null;
}

// The next puzzle in playing order (within the pack), for the win dialog.
export function nextPuzzle(packJson, level, puzzle) {
  const levels = packJson.levels
    .map((l) => l.journeyPosition)
    .filter(Boolean)
    .sort((a, b) => a.level - b.level || a.puzzle - b.puzzle);
  const i = levels.findIndex((p) => p.level === level && p.puzzle === puzzle);
  if (i >= 0 && i + 1 < levels.length) return levels[i + 1];
  return null;
}
